    27	export { PillType } from "./PillType";
    28	
    29	export interface PillProps {
    30	    type?: PillType;
    31	    url?: string;
    32	    inMessage?: boolean;
    33	    room?: Room;
    34	    shouldShowPillAvatar?: boolean;
    35	}
    36	
    37	export function pillRoomNotifPos(text: string): number {
    38	    return text.indexOf("@room");
    39	}
    40	
    41	export function pillRoomNotifLen(): number {
    42	    return "@room".length;
    43	}
    44	
    45	export function Pill({ type, url, inMessage, room, shouldShowPillAvatar }: PillProps): JSX.Element | null {
    46	    const [hovered, setHovered] = useState(false);
    47	    const permalink = usePermalink({ type, url, room });
    48	    if (!permalink.type || !permalink.text) return null;
    49	
    50	    const classes = classNames("mx_Pill", {
    51	        mx_UserPill: permalink.type === PillType.UserMention,
    52	        mx_UserPill_me:
    53	            permalink.type === PillType.UserMention && permalink.resourceId === MatrixClientPeg.get().getUserId(),
    54	        mx_RoomPill: permalink.type === PillType.RoomMention || permalink.type === "space",
    55	        mx_SpacePill: permalink.type === "space",
    56	        mx_AtRoomPill: permalink.type === PillType.AtRoomMention,
    57	    });
    58	    const content = (
    59	        <>
    60	            {shouldShowPillAvatar && permalink.avatar}
    61	            <span className="mx_Pill_linkText">{permalink.text}</span>
    62	            {hovered && permalink.resourceId && <Tooltip label={permalink.resourceId} alignment={Alignment.Right} />}
    63	        </>
    64	    );
    65	    const hoverProps = {
    66	        onMouseOver: (): void => setHovered(true),
    67	        onMouseLeave: (): void => setHovered(false),
    68	    };
    69	
    70	    return (
    71	        <bdi>
    72	            <MatrixClientContext.Provider value={MatrixClientPeg.get()}>
    73	                {inMessage && url ? (
    74	                    <a className={classes} href={url} onClick={permalink.onClick ?? undefined} {...hoverProps}>
    75	                        {content}
    76	                    </a>
    77	                ) : (
    78	                    <span className={classes} {...hoverProps}>
    79	                        {content}
    80	                    </span>
    81	                )}
    82	            </MatrixClientContext.Provider>
    83	        </bdi>
    84	    );
    85	}

