    31	import MemberAvatar from "../components/views/avatars/MemberAvatar";
    32	import { ButtonEvent } from "../components/views/elements/AccessibleButton";
    33	
    34	export interface UsePermalinkArgs {
    35	    room?: Room;
    36	    type?: PillType;
    37	    url?: string;
    38	}
    39	
    40	export interface UsePermalinkResult {
    41	    avatar: ReactElement | null;
    42	    text: string | null;
    43	    onClick: ((e: ButtonEvent) => void) | null;
    44	    resourceId: string | null;
    45	    type: PillType | "space" | null;
    46	}
    47	
    48	const emptyResult: UsePermalinkResult = {
    49	    avatar: null,
    50	    text: null,
    51	    onClick: null,
    52	    resourceId: null,
    53	    type: null,
    54	};
    55	
    56	function roomAvatar(room?: Room): ReactElement | null {
    57	    if (!room) return null;
    58	
    59	    // RoomAvatar also supports a member avatar for DMs. Check that fallback when
    60	    // the direct-message map is available, while omitting empty avatar placeholders.
    61	    if (!room.getMxcAvatarUrl()) {
    62	        const dmMap = DMRoomMap.shared();
    63	        if (!dmMap || (!isLocalRoom(room) && !dmMap.getUserIdForRoomId(room.roomId))) return null;
    64	        if (!room.getAvatarFallbackMember()?.getMxcAvatarUrl()) return null;
    65	    }
    66	    return <RoomAvatar room={room} width={16} height={16} aria-hidden="true" />;
    67	}
    68	
    69	/** Resolve a mention to the information needed to render a pill. */
    70	export function usePermalink({ room, type, url }: UsePermalinkArgs): UsePermalinkResult {
    71	    const entityId = useMemo(() => (url ? getPrimaryPermalinkEntity(url) : null), [url]);
    72	    const inferredType =
    73	        entityId?.[0] === "@" && entityId !== "@room"
    74	            ? PillType.UserMention
    75	            : entityId?.[0] === "!" || entityId?.[0] === "#"
    76	            ? PillType.RoomMention
    77	            : null;
    78	    const effectiveType = type === PillType.AtRoomMention ? type : type ?? inferredType;
    79	    const validEntity = effectiveType === inferredType && !!entityId;
    80	
    81	    const localMember = validEntity && effectiveType === PillType.UserMention ? room?.getMember(entityId) : undefined;
    82	    const fallbackMember = useMemo(
    83	        () =>
    84	            validEntity && effectiveType === PillType.UserMention && !localMember
    85	                ? new RoomMember(null, entityId)
    86	                : null,
    87	        [effectiveType, entityId, localMember, validEntity],
    88	    );
    89	    const [profile, setProfile] = useState<{ userId: string; member: RoomMember } | null>(null);
    90	
    91	    useEffect(() => {
    92	        if (!fallbackMember) return;
    93	
    94	        let active = true;
    95	        MatrixClientPeg.get()
    96	            .getProfileInfo(fallbackMember.userId)
    97	            .then((response) => {
    98	                if (!active) return;
    99	
   100	                const member = new RoomMember(null, fallbackMember.userId);
   101	                member.name = response.displayname || member.userId;
   102	                member.rawDisplayName = response.displayname || member.userId;
   103	                member.events.member = {
   104	                    getContent: () => ({ avatar_url: response.avatar_url }),
   105	                    getDirectionalContent: () => ({ avatar_url: response.avatar_url }),
   106	                } as MatrixEvent;
   107	                setProfile({ userId: member.userId, member });
   108	            })
   109	            .catch((error) => {
   110	                logger.error("Could not retrieve profile data for " + fallbackMember.userId + ":", error);
   111	            });
   112	
   113	        return () => {
   114	            active = false;
   115	        };
   116	    }, [fallbackMember]);
   117	
   118	    if (effectiveType === PillType.AtRoomMention) {
   119	        return {
   120	            avatar: roomAvatar(room),
   121	            text: "@room",
   122	            onClick: null,
   123	            resourceId: room?.roomId ?? null,
   124	            type: PillType.AtRoomMention,
   125	        };
   126	    }
   127	
   128	    if (!validEntity) return emptyResult;
   129	
   130	    if (effectiveType === PillType.RoomMention) {
   131	        const resolvedRoom =
   132	            entityId[0] === "#"
   133	                ? MatrixClientPeg.get()
   134	                      .getRooms()
   135	                      .find(
   136	                          (candidate) =>
   137	                              candidate.getCanonicalAlias() === entityId ||
   138	                              candidate.getAltAliases().includes(entityId),
   139	                      )
   140	                : MatrixClientPeg.get().getRoom(entityId);
   141	
   142	        return {
   143	            avatar: roomAvatar(resolvedRoom),
   144	            text: resolvedRoom?.name || entityId,
   145	            onClick: null,
   146	            resourceId: entityId,
   147	            type: resolvedRoom?.isSpaceRoom() ? "space" : PillType.RoomMention,
   148	        };
   149	    }
   150	
   151	    if (effectiveType === PillType.UserMention) {
   152	        const member = localMember ?? (profile?.userId === entityId ? profile.member : fallbackMember);
   153	        if (!member) return emptyResult;
   154	
   155	        return {
   156	            avatar: member.getMxcAvatarUrl() ? (
   157	                <MemberAvatar member={member} width={16} height={16} aria-hidden="true" hideTitle />
   158	            ) : null,
   159	            text: member.rawDisplayName || member.name || entityId,
   160	            onClick: (e: ButtonEvent): void => {
   161	                e.preventDefault();
   162	                dis.dispatch({ action: Action.ViewUser, member });
   163	            },
   164	            resourceId: entityId,
   165	            type: PillType.UserMention,
   166	        };
   167	    }
   168	
   169	    return emptyResult;
   170	}

